def groupAnagrams(strs):
        hashset = {}

        for s in strs:
            sorted_s = " ".join(sorted(s))

            if sorted_s not in hashset:
                hashset[sorted_s] = [s]
            else:
                hashset[sorted_s].append(s)

        return list(hashset.values())

