let balls=[],valid=false;
function setup() {
  createCanvas(400, 400);

   while(!valid){//!false=true

  for(let i=0;i<20;i++){//creation of the balls  
  balls[i]=new Balls(random(width),random(height),random(20,50));
  }

    for(let i=0;i<balls.length;i++){//1 listing
      for(let j=0;j<balls.length;j++){// 1 copy listing

   if(i!==j&&balls[i].collidesWith(balls[j])) {//balls[0]vs balls[0] does not collide with itself,
     valid=false;
   break;//exits for j loop
   } 
     else{
       valid=true;
     }
   }
  if(!valid)    {//!false=true→exits for i loop
     break;
     }
}
  }//valid=false↑,Overwrites old balls 

}

function draw() {
  background(220);
    for(let ball of balls){
  ball.show();
  ball.move();
      ball.checkEdges();
      for(let other of balls){//ball(0) vs ball(1), same as above
        if(ball!==other&&ball.collidesWith(other)){
          ball.bounceOff(other);
        }
      }
    }
}
class Balls{
  constructor(x,y,d){
    this.x=x;
    this.y=y;
    this.d=d;
    this.sx=random(-2,2);
    this.sy=random(-2,2);
  }
  show(){
    ellipse(this.x,this.y,this.d);
  }
  move(){
    this.x+=this.sx;
    this.y+=this.sy;
  }
  checkEdges(){
    if(this.x<this.d/2||this.x>width-this.d/2){
      this.sx*=-1;
      this.x=constrain(this.x,this.d/2,width-this.d/2);
    }
     if(this.y<this.d/2||this.y>height-this.d/2){
      this.sy*=-1;
       this.y=constrain(this.y,this.d/2,height-this.d/2);
    }

    }
    collidesWith(other){
      let distance=dist(this.x,this.y,other.x,other.y);
     return distance<this.d/2+other.d/2;
  }
  bounceOff(other){
    let tempSx=this.sx;
    let tempSy=this.sy;
    this.sx=other.sx;
    this.sy=other.sy;
    other.sx=tempSx;
    other.sy=tempSy;
  }
}

