class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        length = len(s1) - 1
        currmap = collections.Counter(s1)
        l = 0


        for r in range(len(s2)):
            if s2[r] in currmap:
                currmap[s2[r]] -= 1
            if r > length:
                if s2[l] in currmap:
                    currmap[s2[l]] += 1
                l += 1
            if all(n == 0 for n in currmap.values()):
                return True
        
        return False

