class Solution {
public:
     bool isValid(std::string s) {
    stack<char>st;
    
   if(s.length()==1)return false;
    for(char c : s){
        if(c=='{'||c=='['||c=='('){
            st.push(c);
        }
        else{

            if(st.empty()){
                return false;
            }
            char top=st.top();
            if( (c==']'&&top!='[')|| (c==')'&&top!='(') ||(c=='}'&&top!='{') ){
            
                return false;
            }
            st.pop();
        }

    }
     return st.empty();
    }
};

