Here it is an algorithm using a similar approach but simpler, using only one hashmap of distinct s1 characters to store all occurrences and a set to use as flags for whether a match is pending or not:
class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        dic = {}
        pending = set()
        for char in s1:
            pending.add(char)
            dic[char] = dic.get(char, 0) + 1

        start = 0
        for i, char in enumerate(s2):
            if char in dic:
                dic[char] -= 1
                if dic[char] == 0:
                    pending.remove(char)
                    if len(pending) == 0:
                        return True
            if i + 1 - start == len(s1):
                firstChar = s2[start]
                start += 1
                if firstChar in dic:
                    dic[firstChar] += 1
                    if dic[firstChar] > 0:
                        pending.add(firstChar)

        return False

