def solution(root):
    cache = {}
    return helper(root, cache, 1)

def helper(root, cache, level):
    if not root:
        return True
    cache[level] = root.val # [root.val]

    helper(root.left, cache, level+1)
    helper(root.right, cache, level+1)
    return max(cache.keys())

