public class LinkedStack{
    public LinkedStack Prev = null ;

    public int Val ;

    public int MinVal ;
}

public class MinStack {

private LinkedStack _linkedStack = null;

    public MinStack() {
    }

    
    public void Push(int val) {    
         var newStackItem = _linkedStack == null ? 
         new LinkedStack(){ Prev = null , Val = val , MinVal =val } :
         new LinkedStack(){ Prev = _linkedStack , Val = val , MinVal =val } ;    


         if(_linkedStack != null && val > _linkedStack.MinVal)
         {
            newStackItem.MinVal=_linkedStack.MinVal;
         }
        _linkedStack = newStackItem;
    }
    
    public void Pop() {
        _linkedStack = _linkedStack.Prev;
    }
    
    public int Top() {

        return _linkedStack.Val;
    }
    
    public int GetMin() {
        return _linkedStack.MinVal;
    }
}

