class Solution {
public:
    bool isValidNode(TreeNode* node, long long mini, long long maxi){
        if(node == nullptr){
            return true;
        }
        if(node->val > mini && node->val < maxi){
            return isValidNode(node->left, mini, node->val) && isValidNode(node->right, node->val, maxi);
        }
        else{
            return false;
        }
    }
    bool isValidBST(TreeNode* root) {
        return isValidNode(root, -1000000000000, 1000000000000);
    }
};

