    public static int findMinimum(int[] input) {
        if (input == null || input.length == 0) {
            throw new IllegalArgumentException("Invalid input passed");
        }
        int left = 0, right = input.length - 1, mid = 0;

        while (left != right) {
            mid = (left + right) / 2;
            if (input[mid] >= input[left]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return input[mid];
    }

