// Immediately Invoked Function Expression (IIFE)

// function chai() {
//   console.log(`DB CONNECTED`);
// }
// chai();

// NAMED IIFE: Get rid of global scope's pollution problem,
(function chai() {
  console.log(`DB CONNECTED`);
})(); // ";" is needed to end !!!

//() () // first "()" is for function's definition, and 2nd "()" is for execution call

// SIMPLE IIFE
// can be written this way also
(() => {
  console.log(`DB CONNECTED TWO`);
})(); // ";" is needed!!!!!!
// suppose need to pass a parameter
((name) => {
  console.log(`DB CONNECTED TWO ${name}`);
})("PALASH"); // ";" is needed!!!!!!

