from typing import List

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        anagrams = {}
        for s in strs:
            key = "".join(sorted(s))
            if key in anagrams:
                anagrams[key].append(s)
            else:
                anagrams[key] = [s]
       return list(anagrams.values())

more simpler python 0 ms | beats 100.0% : 

    def generateParenthesis(self, n: int) -> List[str]:
        res=[]
        def backtrack(onum ,cnum,string=None):
            if (onum + cnum )== n*2 :
                res.append(string)
                return
            if onum < (n) :
                backtrack(onum +1 ,cnum,string+"(")
            if cnum < onum :
                backtrack(onum , cnum +1 , string +")")

        backtrack(0,0,"")
        return res

